from TB_LGCL_ENTT e
join TB_LGCL_MDL m on m.LGCL_MDL_SN = e.LGCL_MDL_SN and m.PRJ_SN = 0 and m.MDL_NM = 'LEXORMA'
join TB_TBL t on t.PRJ_SN = 0 and t.TBL_NM = 'TB_AI_EXPLN_EVL_HSTRY'
where e.PRJ_SN = 0 and e.ENTT_NM = 'AI 설명 평가 이력'
  and not exists (select 1 from TB_ENTT_TBL_MPNG x where x.LGCL_ENTT_SN = e.LGCL_ENTT_SN)
  and not exists (select 1 from TB_ENTT_TBL_MPNG x where x.TBL_SN = t.TBL_SN);
insert into TB_ATRB_COL_MPNG(ATRB_COL_MPNG_SN, ENTT_TBL_MPNG_SN, LGCL_ATRB_SN, COL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID)
select next value for SQ_ATRB_COL_MPNG, mp.ENTT_TBL_MPNG_SN, a.LGCL_ATRB_SN, c.COL_SN, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM'
from TB_ENTT_TBL_MPNG mp
join TB_LGCL_ENTT e on e.LGCL_ENTT_SN = mp.LGCL_ENTT_SN and e.ENTT_NM = 'AI 설명 평가 이력'
join TB_TBL t on t.TBL_SN = mp.TBL_SN and t.TBL_NM = 'TB_AI_EXPLN_EVL_HSTRY'
join TB_LGCL_ATRB a on a.LGCL_ENTT_SN = e.LGCL_ENTT_SN
join TB_COL c on c.TBL_SN = t.TBL_SN and c.STD_TRM_SN = a.STD_TRM_SN
where mp.PRJ_SN = 0
  and not exists (select 1 from TB_ATRB_COL_MPNG x where x.LGCL_ATRB_SN = a.LGCL_ATRB_SN)
  and not exists (select 1 from TB_ATRB_COL_MPNG x where x.COL_SN = c.COL_SN);
-- ---------- 예제 : 인덱스 (V2 의 create index 그대로) ----------
insert into TB_TBL_IDX(IDX_SN, PRJ_SN, TBL_SN, IDX_NM, IDX_TYPE_NM, UNQ_YN, APRV_YN, IDX_SRC_CD, DRVN_COL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID)
select next value for SQ_TBL_IDX, 0, t.TBL_SN, 'IX_AI_EXPLN_EVL_HSTRY_01', null, false, true, 'USER', null, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM'
from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_AI_EXPLN_EVL_HSTRY' and not exists (select 1 from TB_TBL_IDX i where i.TBL_SN = t.TBL_SN and i.IDX_NM = 'IX_AI_EXPLN_EVL_HSTRY_01');
insert into TB_TBL_IDX_COL(IDX_COL_SN, IDX_SN, COL_SN, COL_ORD)
select next value for SQ_TBL_IDX_COL, i.IDX_SN, c.COL_SN, 1
from TB_TBL t join TB_TBL_IDX i on i.TBL_SN = t.TBL_SN and i.IDX_NM = 'IX_AI_EXPLN_EVL_HSTRY_01' join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = 'AI_EXPLN_EVL_SN'
where t.PRJ_SN = 0 and t.TBL_NM = 'TB_AI_EXPLN_EVL_HSTRY' and not exists (select 1 from TB_TBL_IDX_COL x where x.IDX_SN = i.IDX_SN);
-- ---------- 예제 : 업무 설명 (예제 테이블·컬럼은 모두 채운다) ----------
update TB_TBL set TASK_EXPLN = '판정을 저장하거나 고칠 때마다 판정자·변경 전후 판정·사유·시각을 추가만 하는 이력. 판정 조작·실수를 추적한다. 지표는 판정 테이블의 최종 판정만 센다.' where PRJ_SN = 0 and TBL_NM = 'TB_AI_EXPLN_EVL_HSTRY' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '판정 변경 이력을 구분하는 내부 번호.' where PRJ_SN = 0 and TBL_NM = 'TB_AI_EXPLN_EVL_HSTRY' and COL_NM = 'AI_EXPLN_EVL_HSTRY_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '이력이 속한 프로젝트. 프로젝트 범위 밖에서는 조회하지 않는다.' where PRJ_SN = 0 and TBL_NM = 'TB_AI_EXPLN_EVL_HSTRY' and COL_NM = 'PRJ_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '바뀐 판정. 판정 행이 지워져도 이력은 남는다.' where PRJ_SN = 0 and TBL_NM = 'TB_AI_EXPLN_EVL_HSTRY' and COL_NM = 'AI_EXPLN_EVL_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '판정한 평가 대상.' where PRJ_SN = 0 and TBL_NM = 'TB_AI_EXPLN_EVL_HSTRY' and COL_NM = 'AI_EXPLN_EVL_TRGT_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '판정한 AI 설명 제안.' where PRJ_SN = 0 and TBL_NM = 'TB_AI_EXPLN_EVL_HSTRY' and COL_NM = 'AI_EXPLN_SGSTN_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '처음 판정(INSERT)인지 판정 수정(UPDATE)인지.' where PRJ_SN = 0 and TBL_NM = 'TB_AI_EXPLN_EVL_HSTRY' and COL_NM = 'CHG_TYPE_CD' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '판정을 저장한 판정자 아이디.' where PRJ_SN = 0 and TBL_NM = 'TB_AI_EXPLN_EVL_HSTRY' and COL_NM = 'RVWR_ID' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '고치기 전 판정 (JSON). 처음 판정이면 비어 있다.' where PRJ_SN = 0 and TBL_NM = 'TB_AI_EXPLN_EVL_HSTRY' and COL_NM = 'CHG_BFR_CN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '저장한 판정 (JSON) : 정확성·근거 없는 주장·누락 정보·불확실성·추천 판정·수정 필요 부분·시간.' where PRJ_SN = 0 and TBL_NM = 'TB_AI_EXPLN_EVL_HSTRY' and COL_NM = 'CHG_AFTR_CN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '판정을 고친 사유. 판정 수정에는 필수다.' where PRJ_SN = 0 and TBL_NM = 'TB_AI_EXPLN_EVL_HSTRY' and COL_NM = 'PRCS_RSN_CN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '판정을 저장한 일시.' where PRJ_SN = 0 and TBL_NM = 'TB_AI_EXPLN_EVL_HSTRY' and COL_NM = 'CHG_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_AI_EXPLN_EVL_HSTRY' and COL_NM = 'REG_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 일시 (감사). 이력은 고치지 않으므로 등록 일시와 같다.' where PRJ_SN = 0 and TBL_NM = 'TB_AI_EXPLN_EVL_HSTRY' and COL_NM = 'MDFCN_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_AI_EXPLN_EVL_HSTRY' and COL_NM = 'RGTR_ID' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_AI_EXPLN_EVL_HSTRY' and COL_NM = 'MDFR_ID' and TASK_EXPLN is null;
-- ---------- 예제 코드 용어 정의 : 처리 유형에 CLOSE_UNCONFIRMABLE 추가 (DEC-29 — 평가 대상의 실제 의미를 확인할 수 없어 종결. ExampleTermCodeDefinitionTest) ----------
-- 사용자가 고친 정의는 건드리지 않는다 (지금 정의가 예전 원문일 때만)
update TB_STD_TRM set TRM_EXPLN = replace(TRM_EXPLN, '·CLOSE(종결).', '·CLOSE(종결)·CLOSE_UNCONFIRMABLE(평가 확인 불가로 종결).') where PRJ_SN = 0 and TRM_NM = '처리_유형_코드' and TRM_EXPLN like '%·CLOSE(종결).' and TRM_EXPLN not like '%CLOSE_UNCONFIRMABLE%';
